import{_ as a,c as o,o as r,ae as t}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"Privacy Choices","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy-choices.md","filePath":"guide/privacy-choices.md","lastUpdated":1795170900000}'),i={name:"guide/privacy-choices.md"};function s(n,e,c,h,d,l){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="privacy-choices" tabindex="-1">Privacy Choices <a class="header-anchor" href="#privacy-choices" aria-label="Permalink to &quot;Privacy Choices&quot;">​</a></h1><p>Simple ways to stay in control.</p><h2 id="browse-without-a-record" tabindex="-1">Browse without a record <a class="header-anchor" href="#browse-without-a-record" aria-label="Permalink to &quot;Browse without a record&quot;">​</a></h2><p>Use a private window (⌘⇧N). It does not add to your history or remember your session, and its tabs disappear when you close it.</p><h2 id="clear-what-is-stored" tabindex="-1">Clear what is stored <a class="header-anchor" href="#clear-what-is-stored" aria-label="Permalink to &quot;Clear what is stored&quot;">​</a></h2><p>Remove cookies and site data from the cookie manager in Settings. You can clear browsing history and downloads from the same area.</p><h2 id="decide-what-each-site-can-do" tabindex="-1">Decide what each site can do <a class="header-anchor" href="#decide-what-each-site-can-do" aria-label="Permalink to &quot;Decide what each site can do&quot;">​</a></h2><p>Camera, microphone and file access are remembered per site. Allow a site you trust and refuse others in Settings. Pop-ups are limited to sites you allow.</p><h2 id="control-background-features" tabindex="-1">Control background features <a class="header-anchor" href="#control-background-features" aria-label="Permalink to &quot;Control background features&quot;">​</a></h2><p>Turn ad-blocking subscriptions on or off in Settings. When one is off, no rule list is fetched.</p><h2 id="choose-your-search-engine" tabindex="-1">Choose your search engine <a class="header-anchor" href="#choose-your-search-engine" aria-label="Permalink to &quot;Choose your search engine&quot;">​</a></h2><p>Pick your default search engine in Settings. Search suggestions come from the engine you choose.</p><h2 id="questions" tabindex="-1">Questions <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions&quot;">​</a></h2><p>Write to <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> if you want to know more about how your data is handled.</p>',14)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
